```cpp
#include <type_traits>
#include <boost/format.hpp>

std::string toStr(boost::format& f) {
    return f.str();
}

template<typename T, typename... Args>
std::string toStr(boost::format& f, T&& t, Args&&... args) {
    return toStr(f % std::forward<T>(t), std::forward<Args>(args)...);
}

template<typename... Args>
std::string print(std::string s, Args&&... args) {
    boost::format f(s);
    return toStr(f, std::forward<Args>(args)...);
}


int main( int argc, char ** argv )
{
    try {
        std::string five("5");
        std::cout << print("%1%+%2%+%3%+%4%+%5%", 2, "3", five, "7.0", 0.1) << std::endl;
        std::cout << print("%d+%s+%s+%s+%f", 2, "3", five, "7.0", 0.1) << std::endl;
    }
    catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
}

```
The only downside is that the format specifiers must start and end with a % when using a number which might be a bit unexpected for Qt users. But it also supports the old C-style format strings.

Here the same with Qt:

```cpp
#include <type_traits>
// This is required
#undef QT_NO_CAST_FROM_ASCII
#include <QString>


std::string toStr(QString& f) {
    return f.toStdString();
}

template<typename T, typename... Args>
std::string toStr(QString& f, T&& t, Args&&... args) {
    return toStr(f.arg(std::forward<T>(t)), std::forward<Args>(args)...);
}

template<typename... Args>
std::string printQStr(std::string s, Args&&... args) {
    QString f(QString::fromStdString(s));
    return toStr(f, std::forward<Args>(args)...);
}


int main( int argc, char ** argv )
{
    std::string five("5");
    std::cout << printQStr("%1+%2+%3+%4+%5", 2, "3", five.c_str(), "7.0", 0.1) << std::endl;
}

```
For the QString approach the define QT_NO_CAST_FROM_ASCII must be unset but this is a bit tricky when pre-compiled headers are activated (on Windows) and you have almost no control over the conversion from float or double to a string because QString may limit the number of decimals.
Also you cannot directly convert from std::string to QString.

IMO, the boost approach is more powerful and it may even work without changing any client code. Also boost raises an exception if the number of format specifiers doesn't match with the number of arguments.

