EDIT:
According to https://en.cppreference.com/w/cpp/thread/mutex/try_lock calling try_lock is even undefined behaviour if the mutex is owned by the thread which calls the function. Since in this case it's the GUI thread it may fail.
Furthermore try_lock is allowed to fail spuriously and return false when it should be true.

I did a performance test between the lock_guard and StateLocker and the former is around 4x slower.
```
// build with g++ main.cpp -lstdc++ -lpthread
#include <iostream>
#include <chrono>
#include <mutex>
#include <thread>

bool flag = false;
std::mutex lockOnChangeMutex;
class StateLocker {
public:
    StateLocker(bool& flag, bool value = true) : lock(flag)
    { old_value = lock; lock = value; }
    ~StateLocker() { lock = old_value; }
private:
    bool& lock;
    bool old_value;
};
unsigned int steps = 100000000;
void func2() {
    if (flag) return;
    StateLocker lock(flag);
    for (unsigned int i=0; i<steps; i++)
        func2();
}

void func1() {
    if (!lockOnChangeMutex.try_lock())
        return;
    lockOnChangeMutex.unlock();
    std::lock_guard<std::mutex> lock(lockOnChangeMutex);
    for (unsigned int i=0; i<steps; i++)
        func1();
}

int main() {
    std::chrono::time_point<std::chrono::system_clock> start, end;
    std::chrono::duration<double> elapsed_seconds;
    // thread 1
    start = std::chrono::system_clock::now();
    std::thread thread1(func1); thread1.join();
    end = std::chrono::system_clock::now();
    elapsed_seconds = end - start;
    std::cout << "elapsed time (lock_guard) : " << elapsed_seconds.count() << "s\n";
    // thread 2
    start = std::chrono::system_clock::now();
    std::thread thread2(func2); thread2.join();
    end = std::chrono::system_clock::now();
    elapsed_seconds = end - start;
    std::cout << "elapsed time (StateLocker): " << elapsed_seconds.count() << "s\n";
}
```

