#include <string>
#include <iostream>
#include <algorithm>
#include <map>
#include <iomanip>


int validColumn(const std::string &colstr)
{
    int col = 0;

    if (colstr.length() == 1) {
        if ((colstr[0] >= 'A' && colstr[0] <= 'Z'))
            col = colstr[0] - 'A';
        else
            return -1;
    }
    else {
        col = 0;
        for (std::string::const_iterator i = colstr.begin(); i != colstr.end(); ++i) {
            int v;

            if ((*i >= 'A' && *i <= 'Z'))
                v = *i - 'A';
            else
                return -1;

            col = col * 26 + v;
        }
        col += 26;
    }
    return col;
}

int decodeColumn(const std::string &colstr, bool silent)
{
    int col = validColumn(colstr);

    if (silent || col >= 0)
        return col;
    else
        return -2;//throw Base::IndexError("Invalid column specification");
}

#include <regex>
#include <cmath>

int validColumn_2(const std::string &colstr)
{
    return std::regex_match(colstr, std::regex("[A-Z]{1,3}")) ? 0 : -1;
}

int convertColumnString(const std::string &colstr){
    double out {0};
    int pos {0};
    for(auto chr = colstr.crbegin(); chr != colstr.crend(); chr++){
      out += (*chr - 64) * std::pow(26, pos++);
    }
    return static_cast<int>(out - 1);
}

int decodeColumn_2(const std::string &colstr, bool silent = false)
{
    if( validColumn_2( colstr ) >= 0 )
        return convertColumnString(colstr);
    if( silent )
        return -1;
    return -2;//throw Base::IndexError("Invalid column specification");
 }
   
