The basic idea is to use a SoNodeSensor and attach it to the camera node. Every time when a field of the camera changes the lambda expression will be invoked. Inside there the new Qt position of the 3D point is computed.

I have tested it inside TaskImageScale::onInteractiveScale() and it works very well. 

This is the complete test code:
```

#include <Inventor/sensors/SoNodeSensor.h>
#include <Inventor/nodes/SoOrthographicCamera.h>

struct NodeData {
    View3DInventorViewer* viewer;
    Gui::QuantitySpinBox* sb;
    SbVec3f coord;
};

void TaskImageScale::onInteractiveScale()
{
    if (!feature.expired() && !scale) {
        View3DInventorViewer* viewer = getViewer();
        if (viewer) {
            auto vp = Application::Instance->getViewProvider(feature.get());
            scale = new InteractiveScale(viewer, vp);
            connect(scale, &InteractiveScale::selectedPoints,
                    this, &TaskImageScale::selectedPoints);
            Gui::QuantitySpinBox* sb = new Gui::QuantitySpinBox(viewer->parentWidget());
            sb->show();

            NodeData* info = new NodeData{viewer, sb, SbVec3f(0,0,0)};

            SoNodeSensor* nodeSensor = new SoNodeSensor([](void * data, SoSensor * sensor) {
                NodeData* info = static_cast<NodeData*>(data);
                auto pos2d = info->viewer->getPointOnViewport(info->coord);
                auto pnt2d = info->viewer->toQPoint(pos2d);
                info->sb->move(pnt2d);
            }, info);

            nodeSensor->attach(viewer->getCamera());
        }
    }

    if (scale) {
        if (scale->isActive()) {
            acceptScale();
        }
        else {
            startScale();
        }
    }
}

```

