StringIDRef StringHasher::getID(const QByteArray& data, Options options) {
    const bool binary = options.testFlag(Option::Binary);
    const bool hashable = options.testFlag(Option::Hashable);
    const bool nocopy = options.testFlag(Option::NoCopy);

    if (hashable && _hashes->Threshold > 0 && data.size() > _hashes->Threshold) {
        QCryptographicHash hasher(QCryptographicHash::Sha1);
        hasher.addData(data);
        const QByteArray hashedData = hasher.result();

        auto it = _hashes->left.find(&hashedData);
        if (it != _hashes->left.end()) {
            return StringIDRef(it->first);
        }

        if (!nocopy) {
            return StringIDRef(insert(StringID(lastID() + 1, hashedData, StringID::Flag::Hashed)));
        }
    }

    const QByteArray copiedData = nocopy ? data : QByteArray(data.constData(), data.size());
    auto it = _hashes->left.find(&copiedData);
    if (it != _hashes->left.end()) {
        return StringIDRef(it->first);
    }

    return StringIDRef(insert(StringID(lastID() + 1, copiedData, binary ? StringID::Flag::Binary : StringID::Flag::None)));
}
```

